    "Widen the main column past the width X fixes it at. Capped to the space available, so a narrow window is unaffected.": "Verbreitert die Hauptspalte über die von X festgelegte Breite hinaus. Auf den verfügbaren Platz begrenzt, ein schmales Fenster bleibt also unverändert.",
