    "Hide engagement counts": "Interaktionszahlen ausblenden",
    "Hide reply, repost, and like numbers. The buttons still work and screen readers still announce the totals.": "Blendet die Zahlen für Antworten, Reposts und Likes aus. Die Schaltflächen funktionieren weiter, und Screenreader nennen die Summen weiterhin.",
    "Hide row borders": "Zeilentrenner ausblenden",
