    "Writer mode": "Schreibmodus",
    "While focus is in the composer, fade the sidebar and the timeline behind it. Everything returns the moment you click away.": "Solange der Fokus im Verfasser liegt, treten Seitenleiste und Timeline dahinter zurück. Alles kehrt zurück, sobald Sie daneben klicken.",
