    "Walks every tweet rendered on the current page and queues every photo/video/GIF/thumbnail through the existing download pipeline.": "Durchläuft jeden Beitrag auf der aktuellen Seite und stellt jedes Foto, Video, GIF und Vorschaubild in die bestehende Download-Warteschlange.",
    "Capture visible tweets": "Sichtbare Beiträge erfassen",
