    "Preserve raw payloads": "Rohdaten aufbewahren",
    "Also store the raw GraphQL responses X sends this tab, so records can be re-parsed later. Session tokens are stripped before anything is written.": "Speichert zusätzlich die rohen GraphQL-Antworten, die X an diesen Tab sendet, damit Datensätze später neu ausgewertet werden können. Sitzungstoken werden vor dem Schreiben entfernt.",
