    "Aviary never deletes posts, likes, or follows. The queue is a review list; approving or skipping only writes to the audit log.": "Aviary löscht niemals Beiträge, Likes oder Follows. Die Liste dient nur der Prüfung; Zustimmen oder Überspringen schreibt lediglich ins Prüfprotokoll.",
    "Enqueue cleanup preview for review": "Bereinigungsvorschau zur Prüfung einreihen",
    "Append every non-protected candidate from the latest cleanup preview to the queue (no destructive action).": "Fügt alle ungeschützten Kandidaten der letzten Bereinigungsvorschau der Liste hinzu (keine destruktive Aktion).",
    "Clear cleanup queue": "Bereinigungsliste leeren",
    "Drop every queued item without touching account data.": "Entfernt alle Einträge der Liste, ohne Kontodaten anzurühren.",
    "Aria2 handoff": "Aria2-Übergabe",
