    "Rebuild semantic index": "Semantischen Index neu aufbauen",
    "Embed every captured record. Re-running is cheap because cached entries are skipped.": "Erzeugt Embeddings für jeden erfassten Datensatz. Ein erneuter Lauf ist günstig, da zwischengespeicherte Einträge übersprungen werden.",
