    "Downloads your preferences as JSON. API keys and passwords are replaced with a placeholder, so the file is safe to share; importing it here keeps the credentials already saved on this machine.": "Lädt deine Einstellungen als JSON herunter. API-Schlüssel und Passwörter werden durch einen Platzhalter ersetzt, die Datei lässt sich also gefahrlos weitergeben; beim Import hier bleiben die auf diesem Rechner gespeicherten Zugangsdaten erhalten.",
    "Import settings (JSON)": "Einstellungen importieren (JSON)",
