    "Hide row borders": "行の境界線を非表示",
    "Remove the 1px divider under each timeline post and the primary column's side rules.": "各投稿の下にある 1px の区切り線と、メインカラムの左右の罫線を消します。",
    "High contrast": "ハイコントラスト",
    "Use stronger borders and text contrast.": "境界線と文字のコントラストを強めます。",
    "Reduced motion": "視差効果を減らす",
    "Follow system setting": "システム設定に従う",
    "Always reduce": "常に減らす",
    "Never reduce": "減らさない",
    "Hide right sidebar": "右サイドバーを非表示",
    "Reduce trends, recommendations, and footer noise.": "トレンド・おすすめ・フッターのノイズを減らします。",
    "Hide trends": "トレンドを非表示",
    "Remove trending topics and news modules.": "トレンドとニュースのモジュールを消します。",
    "Hide Grok surfaces": "Grok の要素を非表示",
    "Remove Grok drawer and composer buttons where detected.": "検出できた Grok のドロワーと投稿欄のボタンを消します。",
    "Writer mode": "ライターモード",
    "While focus is in the composer, fade the sidebar and the timeline behind it. Everything returns the moment you click away.": "投稿欄にフォーカスがある間、サイドバーと背後のタイムラインを薄くします。別の場所をクリックすればすぐ元に戻ります。",
    "Open Following instead of For you": "「おすすめ」ではなく「フォロー中」を開く",
    "Selects the second home tab each time you arrive at the timeline. Switch back to For you and it stays there until you navigate away.": "タイムラインを開くたびにホームの2番目のタブを選びます。「おすすめ」に戻した場合は、ページを離れるまでそのままです。",
    "Enable filters": "フィルタを有効にする",
    "Master switch for keyword, regex, premium, and media filters.": "キーワード・正規表現・プレミアム・メディアの各フィルタをまとめて切り替えます。",
    "Keyword rules": "キーワードのルール",
    "One keyword or phrase per line. Case-insensitive substring match.": "1 行に 1 つのキーワードまたはフレーズ。大文字小文字を区別しない部分一致です。",
    "Save list": "リストを保存",
    "Regex rules": "正規表現のルール",
    "One pattern per line. Use /pattern/flags or a bare pattern (case-insensitive).": "1 行に 1 つのパターン。/pattern/flags 形式か、そのままのパターン（大文字小文字を区別しません）。",
    "Whitelist handles": "除外するアカウント",
    "Handles (one per line, no @) that are never filtered.": "フィルタしないアカウント名（1 行に 1 つ、@ なし）。",
    "Premium / verified posts": "プレミアム・認証済みの投稿",
    "Off": "オフ",
    "Hide": "非表示",
    "Hide posts with photos": "写真付きの投稿を非表示",
    "Filter posts containing photos.": "写真を含む投稿をフィルタします。",
    "Hide posts with videos": "動画付きの投稿を非表示",
    "Filter posts containing videos.": "動画を含む投稿をフィルタします。",
    "Hide posts with gifs": "GIF 付きの投稿を非表示",
    "Filter posts containing gifs.": "GIF を含む投稿をフィルタします。",
    "Active on": "適用するページ",
    "Routes where filters run.": "フィルタを実行するページ。",
