    "Status": "投稿",
    "Profile": "プロフィール",
    "Search": "検索",
    "Notifications": "通知",
    "Messages": "メッセージ",
    "Blocked accounts / self-reposts": "ブロック済みアカウント・自分のリポスト",
    "Pending an authenticated fixture; controls stay disabled.": "認証済みのフィクスチャ待ちのため、この設定は無効のままです。",
    "Hide dismissed posts": "閉じた投稿を非表示",
