    "Forgets every hidden post and brings them all back.": "숨긴 게시물을 모두 잊고 되돌립니다.",
    "Pause video that scrolls out of view": "화면 밖으로 나간 동영상 일시정지",
    "Stops decoding timeline video once it leaves the screen, and resumes it when it comes back. A video you paused yourself stays paused.": "타임라인 동영상이 화면 밖으로 나가면 디코딩을 멈추고, 다시 보이면 재생합니다. 직접 일시정지한 동영상은 그대로 유지됩니다.",
    "Show download buttons": "다운로드 버튼 표시",
    "Inject Save and Thumb buttons over tweet photos and video thumbnails.": "게시물의 사진과 동영상 썸네일 위에 저장·썸네일 버튼을 추가합니다.",
    "Prefer original quality": "원본 화질 우선",
    "Rewrite image URLs to name=orig before downloading.": "내려받기 전에 이미지 URL을 name=orig로 바꿉니다.",
