    "Also store the raw GraphQL responses X sends this tab, so records can be re-parsed later. Session tokens are stripped before anything is written.": "X가 이 탭에 보내는 GraphQL 원본 응답도 저장해 나중에 다시 해석할 수 있게 합니다. 저장 전에 세션 토큰은 제거됩니다.",
