    "Save folder hint": "저장 폴더",
    "Folder name (or path) used as the export ZIP root and download prefix.": "내보내기 ZIP의 최상위 폴더이자 다운로드 이름 앞에 붙일 폴더 이름(또는 경로).",
    "Export status": "내보내기 상태",
    "Export visible tweets": "표시된 게시물 내보내기",
    "Collect the currently rendered tweets and download a ZIP.": "현재 표시된 게시물을 모아 ZIP으로 내려받습니다.",
    "Copy diagnostics": "진단 정보 복사",
    "Copy support diagnostics (version, route, recent log).": "지원용 진단 정보(버전, 경로, 최근 로그)를 복사합니다.",
    "Download as WARC": "WARC로 내려받기",
    "Wrap captured records into an ISO-28500 WARC file for research / preservation tooling.": "수집한 기록을 ISO-28500 WARC 파일로 묶어 연구·보존 도구에서 쓸 수 있게 합니다.",
    "Copy as Markdown": "Markdown으로 복사",
    "Push a plain Markdown export onto the clipboard.": "일반 Markdown 결과를 클립보드에 복사합니다.",
    "Save Obsidian Markdown": "Obsidian용 Markdown 저장",
    "Markdown with YAML frontmatter and Aviary tags.": "YAML 머리말과 Aviary 태그가 포함된 Markdown.",
    "Save Notion Markdown": "Notion용 Markdown 저장",
