    "Records per ZIP": "ZIP당 기록 수",
    "Split a long export across several archives instead of one huge file (25-1000).": "긴 내보내기를 하나의 거대한 파일 대신 여러 아카이브로 나눕니다(25~1000).",
    "Maximum export jobs": "내보내기 작업 최대 수",
    "Keep the newest jobs. Use 0 for unlimited.": "최신 작업을 유지합니다. 0은 무제한입니다.",
    "Maximum records per job": "작업당 기록 최대 수",
    "Keep the newest records in each job. Use 0 for unlimited.": "각 작업의 최신 기록을 유지합니다. 0은 무제한입니다.",
    "Maximum export age (days)": "내보내기 보관 기간(일)",
    "Remove older jobs at boot. Use 0 to disable age-based cleanup.": "시작할 때 오래된 작업을 지웁니다. 0이면 기간 기준 정리를 끕니다.",
    "Unshorten t.co links": "t.co 링크 펼치기",
    "Replace short `t.co` redirects with the destination from aria-labels and titles.": "짧은 `t.co` 링크를 aria-label과 title에 있는 실제 주소로 바꿉니다.",
    "Clean tracking from links": "링크에서 추적 정보 제거",
    "Strips share tokens and campaign parameters (utm_*, fbclid, and X's own t/s) from links in the timeline, so what you copy is the plain address.": "타임라인 링크에서 공유 토큰과 캠페인 매개변수(utm_*, fbclid, X 자체의 t/s)를 제거해 복사한 내용이 순수한 주소가 되도록 합니다.",
    "Account notes": "계정 메모",
    "Format: handle: note. One per line. Empty notes remove the entry.": "형식: 계정: 메모. 한 줄에 하나씩. 메모를 비우면 삭제됩니다.",
    "Clear all account notes": "계정 메모 모두 지우기",
    "Drop every persisted note.": "저장된 메모를 모두 삭제합니다.",
    "Composer snippets": "상용구",
    "One snippet per line. Reusable replies / templates (insertion landing in a later release).": "한 줄에 하나씩. 다시 쓸 수 있는 답글이나 템플릿입니다(삽입 기능은 이후 릴리스에서 지원).",
    "Snapshots stored": "저장된 스냅샷",
    "Capture followers from this view": "이 화면에서 팔로워 수집",
