    "Cleanup review queue": "정리 검토 대기열",
    "Destructive actions": "파괴적인 작업",
    "Aviary never deletes posts, likes, or follows. The queue is a review list; approving or skipping only writes to the audit log.": "Aviary는 게시물·마음에 들어요·팔로우를 삭제하지 않습니다. 이 대기열은 검토용 목록이며, 승인하거나 건너뛰어도 감사 로그에만 기록됩니다.",
    "Enqueue cleanup preview for review": "정리 미리보기를 대기열에 추가",
