    "Smaller files save through the browser. Aviary checks the size first; when the server will not report one, the file is handed off anyway.": "이보다 작은 파일은 브라우저로 저장합니다. Aviary가 먼저 크기를 확인하며, 서버가 크기를 알려주지 않으면 그대로 전달합니다.",
