    "Bluesky app password": "Bluesky 앱 비밀번호",
    "App password from your account settings — never your main password.": "계정 설정에서 발급한 앱 비밀번호. 기본 비밀번호는 쓰지 마세요.",
    "Mastodon crosspost": "Mastodon 교차 게시",
