    "Crosspost composer → Mastodon": "작성창을 Mastodon으로",
    "AI provider runs": "AI 제공자 실행",
    "Let the AI command menu POST prompts to your configured provider.": "AI 명령 메뉴가 설정한 제공자에게 프롬프트를 보낼 수 있게 합니다.",
