    "OpenAI-compatible (LocalAI, Ollama proxy, …)": "OpenAI 호환(LocalAI, Ollama 프록시 등)",
    "AI endpoint (optional)": "AI 엔드포인트(선택)",
    "Override the default endpoint for the chosen provider.": "선택한 제공자의 기본 엔드포인트를 대체합니다.",
    "AI model": "AI 모델",
    "e.g. claude-sonnet-4-6, gpt-4o, llama3.1:8b": "예: claude-sonnet-4-6, gpt-4o, llama3.1:8b",
    "AI API key": "AI API 키",
    "Stored locally only. Aviary never sends this except as the auth header to your provider.": "로컬에만 저장됩니다. Aviary는 설정한 제공자의 인증 헤더 외에는 이 값을 보내지 않습니다.",
    "Semantic search": "의미 기반 검색",
    "Embed CheckpointStore records via your provider for similarity search.": "유사도 검색을 위해 CheckpointStore 기록을 제공자로 임베딩합니다.",
    "Embedding endpoint": "임베딩 엔드포인트",
