    "Embedding model": "임베딩 모델",
    "e.g. text-embedding-3-small": "예: text-embedding-3-small",
    "Embedding API key": "임베딩 API 키",
    "Stored locally; used only as the Authorization header.": "로컬에 저장되며 Authorization 헤더로만 사용됩니다.",
    "Auto-embed every export": "내보낼 때마다 자동 임베딩",
    "After each export run, kick the embedding job in the background. Off by default.": "내보내기를 마칠 때마다 임베딩 작업을 백그라운드에서 시작합니다. 기본은 꺼짐입니다.",
    "Rebuild semantic index": "의미 색인 다시 만들기",
    "Embed every captured record. Re-running is cheap because cached entries are skipped.": "수집한 모든 기록을 임베딩합니다. 캐시된 항목은 건너뛰므로 다시 실행해도 부담이 적습니다.",
    "Clear semantic index": "의미 색인 지우기",
    "Forget every embedded record.": "임베딩된 기록을 모두 잊습니다.",
    "Integration status": "연동 상태",
    "Export settings": "설정 내보내기",
    "Downloads your preferences as JSON. API keys and passwords are replaced with a placeholder, so the file is safe to share; importing it here keeps the credentials already saved on this machine.": "설정을 JSON으로 내려받습니다. API 키와 비밀번호는 자리표시자로 바뀌므로 공유해도 안전합니다. 여기서 가져오면 이 컴퓨터에 저장된 인증 정보는 그대로 유지됩니다.",
    "Import settings (JSON)": "설정 가져오기(JSON)",
    "Paste a settings file exported from Aviary, then choose Import. Redacted credentials keep the values already saved here.": "Aviary에서 내보낸 설정 파일을 붙여 넣고 가져오기를 누르세요. 가려진 인증 정보는 여기에 저장된 값이 유지됩니다.",
    "Import": "가져오기",
    "Keep a local action log": "로컬 작업 로그 유지",
    "Records downloads, exports and settings changes on this device so you can review what Aviary did. Nothing is sent anywhere. Turning this off stops new entries immediately; existing ones stay until you clear them.": "다운로드, 내보내기, 설정 변경을 이 기기에 기록해 Aviary가 무엇을 했는지 확인할 수 있게 합니다. 외부로 전송되지 않습니다. 끄면 새 기록이 즉시 중단되며, 기존 기록은 지울 때까지 남습니다.",
    "Audit entries": "감사 기록 수",
    "Clear audit log": "감사 로그 지우기",
    "Drop the local action log.": "로컬 작업 로그를 삭제합니다.",
    "Storage": "저장 위치",
    "Settings stay in this browser.": "설정은 이 브라우저에만 남습니다.",
    "Local-only mode": "로컬 전용 모드",
    "Blocks every outbound request, including the integrations you configured. On by default; turning an integration on is what turns this off.": "설정한 연동을 포함해 모든 외부 요청을 차단합니다. 기본으로 켜져 있으며, 연동을 켜면 이 모드가 꺼집니다.",
    "Some changes could not be saved — the browser store may be full.": "일부 변경 사항을 저장하지 못했습니다. 브라우저 저장 공간이 가득 찼을 수 있습니다.",
    "Saving": "저장",
    "Telemetry": "텔레메트리",
    "Disabled": "사용 안 함",
    "Panel language": "패널 언어",
    "Selector health": "선택자 상태",
    "Theme value is not supported.": "지원하지 않는 테마입니다.",
