    "While focus is in the composer, fade the sidebar and the timeline behind it. Everything returns the moment you click away.": "أثناء التركيز على محرر المنشور، يخفت الشريط الجانبي والخط الزمني خلفه. يعود كل شيء بمجرد النقر خارجه.",
    "Open Following instead of For you": "فتح «المتابَعون» بدلًا من «لك»",
    "Selects the second home tab each time you arrive at the timeline. Switch back to For you and it stays there until you navigate away.": "يحدد علامة التبويب الثانية في الصفحة الرئيسية في كل مرة تصل فيها إلى الخط الزمني. وإذا عدت إلى «لك» فسيبقى كذلك حتى تغادر الصفحة.",
    "Enable filters": "تفعيل الفلاتر",
