    "Stops decoding timeline video once it leaves the screen, and resumes it when it comes back. A video you paused yourself stays paused.": "يوقف فك ترميز فيديو الخط الزمني عند خروجه من الشاشة، ويستأنفه عند عودته. الفيديو الذي أوقفته بنفسك يبقى متوقفًا.",
    "Show download buttons": "إظهار أزرار التنزيل",
