    "Prefer original quality": "تفضيل الجودة الأصلية",
    "Rewrite image URLs to name=orig before downloading.": "يعيد كتابة روابط الصور إلى name=orig قبل التنزيل.",
    "Show images at original quality": "عرض الصور بالجودة الأصلية",
    "Loads timeline photos at full size instead of the version X picks for the slot. Sharper, and several times the bytes.": "يحمّل صور الخط الزمني بالحجم الكامل بدلًا من النسخة التي يختارها X للمساحة المتاحة. أوضح، لكن باستهلاك بيانات أكبر بعدة أضعاف.",
