    "Download all visible media": "تنزيل كل الوسائط الظاهرة",
    "Walks every tweet rendered on the current page and queues every photo/video/GIF/thumbnail through the existing download pipeline.": "يمرّ على كل منشور معروض في الصفحة الحالية ويضيف كل صورة وفيديو وGIF ومصغّرة إلى طابور التنزيل الحالي.",
    "Capture visible tweets": "جمع المنشورات الظاهرة",
