    "Export formats": "صيغ التصدير",
    "Comma-separated list. Supported: json, csv, html, markdown, xlsx.": "قائمة مفصولة بفواصل. المدعوم: json، csv، html، markdown، xlsx.",
    "Preserve raw payloads": "حفظ الاستجابات الخام",
    "Also store the raw GraphQL responses X sends this tab, so records can be re-parsed later. Session tokens are stripped before anything is written.": "يحفظ أيضًا استجابات GraphQL الخام التي يرسلها X إلى هذه التبويبة، ليمكن تحليلها لاحقًا. تُزال رموز الجلسة قبل الكتابة.",
    "Auto-discover query IDs": "اكتشاف معرّفات الاستعلام تلقائيًا",
    "Scan loaded scripts for X GraphQL operation IDs and cache them locally.": "يفحص السكربتات المحمّلة بحثًا عن معرّفات عمليات GraphQL في X ويخزّنها محليًا.",
    "Save folder hint": "مجلد الحفظ",
    "Folder name (or path) used as the export ZIP root and download prefix.": "اسم المجلد (أو المسار) المستخدم كجذر لملف ZIP وكبادئة للتنزيل.",
    "Export status": "حالة التصدير",
    "Export visible tweets": "تصدير المنشورات الظاهرة",
    "Collect the currently rendered tweets and download a ZIP.": "يجمع المنشورات المعروضة حاليًا وينزّلها كملف ZIP.",
    "Copy diagnostics": "نسخ معلومات التشخيص",
    "Copy support diagnostics (version, route, recent log).": "ينسخ معلومات الدعم (الإصدار، الصفحة، آخر السجل).",
    "Download as WARC": "التنزيل بصيغة WARC",
    "Wrap captured records into an ISO-28500 WARC file for research / preservation tooling.": "يغلّف السجلات المجمّعة في ملف WARC وفق ISO-28500 لأدوات البحث والحفظ.",
    "Copy as Markdown": "نسخ بصيغة Markdown",
    "Push a plain Markdown export onto the clipboard.": "ينسخ تصديرًا بصيغة Markdown بسيطة إلى الحافظة.",
    "Save Obsidian Markdown": "حفظ Markdown لـ Obsidian",
    "Markdown with YAML frontmatter and Aviary tags.": "Markdown مع ترويسة YAML ووسوم Aviary.",
    "Save Notion Markdown": "حفظ Markdown لـ Notion",
    "Heading-first Markdown that Notion imports cleanly.": "Markdown يعتمد على العناوين ويستورده Notion بسلاسة.",
    "Save records JSON": "حفظ السجلات بصيغة JSON",
    "Raw ExportRecord[] JSON without ZIP wrapping.": "‏JSON خام من نوع ExportRecord[] دون تغليف ZIP.",
    "Records per ZIP": "عدد السجلات لكل ZIP",
    "Split a long export across several archives instead of one huge file (25-1000).": "يقسّم عمليات التصدير الطويلة على عدة ملفات بدل ملف واحد ضخم (25-1000).",
    "Maximum export jobs": "الحد الأقصى لمهام التصدير",
    "Keep the newest jobs. Use 0 for unlimited.": "يحتفظ بأحدث المهام. استخدم 0 لعدد غير محدود.",
    "Maximum records per job": "الحد الأقصى للسجلات لكل مهمة",
    "Keep the newest records in each job. Use 0 for unlimited.": "يحتفظ بأحدث السجلات في كل مهمة. استخدم 0 لعدد غير محدود.",
    "Maximum export age (days)": "أقصى عمر للتصدير (بالأيام)",
    "Remove older jobs at boot. Use 0 to disable age-based cleanup.": "يحذف المهام الأقدم عند البدء. استخدم 0 لتعطيل التنظيف حسب العمر.",
    "Unshorten t.co links": "توسيع روابط t.co",
    "Replace short `t.co` redirects with the destination from aria-labels and titles.": "يستبدل روابط `t.co` المختصرة بالوجهة المأخوذة من aria-label والعناوين.",
    "Clean tracking from links": "إزالة التتبّع من الروابط",
    "Strips share tokens and campaign parameters (utm_*, fbclid, and X's own t/s) from links in the timeline, so what you copy is the plain address.": "يزيل رموز المشاركة ومعاملات الحملات (utm_* وfbclid ومعاملات t/s الخاصة بـ X) من روابط الخط الزمني، فيصبح ما تنسخه هو العنوان المجرّد.",
    "Account notes": "ملاحظات الحسابات",
    "Format: handle: note. One per line. Empty notes remove the entry.": "الصيغة: الحساب: الملاحظة. واحدة في كل سطر. الملاحظة الفارغة تحذف العنصر.",
    "Clear all account notes": "مسح كل ملاحظات الحسابات",
    "Drop every persisted note.": "يحذف كل الملاحظات المحفوظة.",
    "Composer snippets": "النصوص الجاهزة",
