    "Snapshots stored": "اللقطات المحفوظة",
    "Capture followers from this view": "جمع المتابِعين من هذه الصفحة",
    "Walks UserCell rows on the current page. Open a /handle/followers view first.": "يمرّ على صفوف UserCell في الصفحة الحالية. افتح أولًا صفحة ‎/الحساب/followers‎.",
    "Capture following from this view": "جمع المتابَعين من هذه الصفحة",
    "Walks UserCell rows on the current page. Open a /handle/following view first.": "يمرّ على صفوف UserCell في الصفحة الحالية. افتح أولًا صفحة ‎/الحساب/following‎.",
    "Clear all snapshots": "مسح كل اللقطات",
    "Drop every stored follower/following snapshot.": "يحذف كل لقطات المتابِعين والمتابَعين المحفوظة.",
    "Download Markdown report": "تنزيل تقرير Markdown",
    "Audit log + snapshot diff + cleanup preview.": "سجل التدقيق ومقارنة اللقطات ومعاينة التنظيف.",
    "Cleanup review queue": "قائمة مراجعة التنظيف",
    "Destructive actions": "الإجراءات المدمّرة",
    "Aviary never deletes posts, likes, or follows. The queue is a review list; approving or skipping only writes to the audit log.": "لا يحذف Aviary أي منشورات أو إعجابات أو متابعات. القائمة للمراجعة فقط؛ والموافقة أو التخطي يُسجَّلان في سجل التدقيق لا أكثر.",
    "Enqueue cleanup preview for review": "إضافة معاينة التنظيف إلى القائمة",
    "Append every non-protected candidate from the latest cleanup preview to the queue (no destructive action).": "يضيف إلى القائمة كل المرشحين غير المحميين من آخر معاينة تنظيف (دون أي إجراء مدمّر).",
