    "Aria2 handoff": "التسليم إلى Aria2",
    "Send large media downloads to a self-hosted Aria2 JSON-RPC endpoint.": "يرسل تنزيلات الوسائط الكبيرة إلى نقطة Aria2 JSON-RPC مستضافة ذاتيًا.",
