    "Show": "إظهار",
    "Hand off files larger than (MB)": "تسليم الملفات الأكبر من (ميغابايت)",
    "Smaller files save through the browser. Aviary checks the size first; when the server will not report one, the file is handed off anyway.": "تُحفظ الملفات الأصغر عبر المتصفح. يتحقق Aviary من الحجم أولًا، وإذا لم يذكره الخادم فسيتم تسليم الملف على أي حال.",
    "Test Aria2 connection": "اختبار الاتصال بـ Aria2",
    "Sends a trivial JSON-RPC call.": "يرسل طلب JSON-RPC بسيطًا.",
    "Refresh": "تحديث",
    "Bluesky crosspost": "النشر المتقاطع على Bluesky",
    "Post composer text to your Bluesky account on demand.": "ينشر نص المحرر على حسابك في Bluesky عند الطلب.",
    "Bluesky service URL": "رابط خدمة Bluesky",
    "Default: https://bsky.social": "الافتراضي: https://bsky.social",
