    "Mastodon crosspost": "النشر المتقاطع على Mastodon",
    "Post composer text to your Mastodon account on demand.": "ينشر نص المحرر على حسابك في Mastodon عند الطلب.",
    "Mastodon instance": "خادم Mastodon",
    "https://mastodon.social": "https://mastodon.social",
    "Mastodon access token": "رمز وصول Mastodon",
    "Bearer token with write:statuses scope.": "رمز Bearer بنطاق write:statuses.",
    "Attach last download": "إرفاق آخر تنزيل",
    "Upload the last successful Aviary media download with the first post in an explicit crosspost.": "يرفع آخر وسائط نزّلها Aviary بنجاح مع أول منشور في النشر المتقاطع.",
    "Crosspost composer → Bluesky": "نشر المحرر على Bluesky",
    "Uses the current composer text.": "يستخدم النص الحالي في المحرر.",
    "Crosspost composer → Mastodon": "نشر المحرر على Mastodon",
    "AI provider runs": "تشغيل مزوّد الذكاء الاصطناعي",
    "Let the AI command menu POST prompts to your configured provider.": "يسمح لقائمة أوامر الذكاء الاصطناعي بإرسال الطلبات إلى المزوّد الذي أعددته.",
    "AI provider": "مزوّد الذكاء الاصطناعي",
    "Anthropic Messages API": "Anthropic Messages API",
    "OpenAI Chat Completions": "OpenAI Chat Completions",
    "OpenAI-compatible (LocalAI, Ollama proxy, …)": "متوافق مع OpenAI (LocalAI، وسيط Ollama، …)",
    "AI endpoint (optional)": "نقطة الذكاء الاصطناعي (اختياري)",
    "Override the default endpoint for the chosen provider.": "يتجاوز النقطة الافتراضية للمزوّد المختار.",
    "AI model": "نموذج الذكاء الاصطناعي",
    "e.g. claude-sonnet-4-6, gpt-4o, llama3.1:8b": "مثال: claude-sonnet-4-6، gpt-4o، llama3.1:8b",
    "AI API key": "مفتاح API للذكاء الاصطناعي",
    "Stored locally only. Aviary never sends this except as the auth header to your provider.": "يُحفظ محليًا فقط. لا يرسله Aviary إلا كترويسة مصادقة إلى مزوّدك.",
    "Semantic search": "البحث الدلالي",
    "Embed CheckpointStore records via your provider for similarity search.": "يحوّل سجلات CheckpointStore إلى متجهات عبر مزوّدك للبحث بالتشابه.",
    "Embedding endpoint": "نقطة التضمين",
    "POST endpoint that returns {data: [{embedding: number[]}]}": "نقطة POST تُعيد {data: [{embedding: number[]}]}",
    "Embedding model": "نموذج التضمين",
    "e.g. text-embedding-3-small": "مثال: text-embedding-3-small",
    "Embedding API key": "مفتاح API للتضمين",
    "Stored locally; used only as the Authorization header.": "يُحفظ محليًا، ويُستخدم فقط كترويسة Authorization.",
    "Auto-embed every export": "التضمين التلقائي بعد كل تصدير",
    "After each export run, kick the embedding job in the background. Off by default.": "بعد كل عملية تصدير، يبدأ التضمين في الخلفية. معطّل افتراضيًا.",
    "Rebuild semantic index": "إعادة بناء الفهرس الدلالي",
    "Embed every captured record. Re-running is cheap because cached entries are skipped.": "يضمّن كل سجل مجمّع. إعادة التشغيل غير مكلفة لأن العناصر المخزّنة تُتخطّى.",
    "Clear semantic index": "مسح الفهرس الدلالي",
    "Forget every embedded record.": "ينسى كل السجلات المضمّنة.",
    "Integration status": "حالة التكاملات",
    "Export settings": "تصدير الإعدادات",
    "Downloads your preferences as JSON. API keys and passwords are replaced with a placeholder, so the file is safe to share; importing it here keeps the credentials already saved on this machine.": "ينزّل تفضيلاتك بصيغة JSON. تُستبدل مفاتيح API وكلمات المرور بعنصر نائب، فيصبح الملف آمنًا للمشاركة؛ واستيراده هنا يبقي بيانات الاعتماد المحفوظة على هذا الجهاز.",
    "Import settings (JSON)": "استيراد الإعدادات (JSON)",
    "Paste a settings file exported from Aviary, then choose Import. Redacted credentials keep the values already saved here.": "الصق ملف إعدادات مُصدَّرًا من Aviary ثم اختر استيراد. بيانات الاعتماد المحجوبة تحتفظ بالقيم المحفوظة هنا.",
    "Import": "استيراد",
    "Keep a local action log": "الاحتفاظ بسجل محلي للإجراءات",
    "Records downloads, exports and settings changes on this device so you can review what Aviary did. Nothing is sent anywhere. Turning this off stops new entries immediately; existing ones stay until you clear them.": "يسجّل التنزيلات وعمليات التصدير وتغييرات الإعدادات على هذا الجهاز لتتمكن من مراجعة ما فعله Aviary. لا يُرسل أي شيء إلى أي جهة. إيقافه يمنع إضافة أي عناصر جديدة فورًا، وتبقى العناصر الحالية حتى تمسحها.",
    "Audit entries": "عناصر سجل التدقيق",
    "Clear audit log": "مسح سجل التدقيق",
