    "Download as WARC": "הורדה כ‑WARC",
    "Wrap captured records into an ISO-28500 WARC file for research / preservation tooling.": "עוטף את הרשומות שנאספו בקובץ WARC לפי ISO-28500 עבור כלי מחקר ושימור.",
