    "Maximum export age (days)": "גיל ייצוא מרבי (ימים)",
    "Remove older jobs at boot. Use 0 to disable age-based cleanup.": "מוחק משימות ישנות בהפעלה. 0 מבטל ניקוי לפי גיל.",
