    "Replace short `t.co` redirects with the destination from aria-labels and titles.": "מחליף קישורי `t.co` מקוצרים ביעד שמופיע ב‑aria-label ובכותרות.",
    "Clean tracking from links": "ניקוי מעקב מקישורים",
