    "Aviary never deletes posts, likes, or follows. The queue is a review list; approving or skipping only writes to the audit log.": "‏Aviary לעולם אינו מוחק פוסטים, לייקים או עוקבים. התור הוא רשימת בדיקה בלבד; אישור או דילוג נרשמים רק ביומן הביקורת.",
