    "Smaller files save through the browser. Aviary checks the size first; when the server will not report one, the file is handed off anyway.": "קבצים קטנים יותר נשמרים דרך הדפדפן. Aviary בודק קודם את הגודל, ואם השרת אינו מדווח עליו הקובץ מועבר בכל זאת.",
    "Test Aria2 connection": "בדיקת החיבור ל‑Aria2",
