    "Attach last download": "צירוף ההורדה האחרונה",
    "Upload the last successful Aviary media download with the first post in an explicit crosspost.": "מעלה את המדיה האחרונה ש‑Aviary הוריד בהצלחה יחד עם הפוסט הראשון בפרסום מקביל.",
    "Crosspost composer → Bluesky": "פרסום חלון הכתיבה ב‑Bluesky",
