    "Anthropic Messages API": "Anthropic Messages API",
    "OpenAI Chat Completions": "OpenAI Chat Completions",
    "OpenAI-compatible (LocalAI, Ollama proxy, …)": "תואם OpenAI ‏(LocalAI, פרוקסי Ollama, …)",
    "AI endpoint (optional)": "נקודת קצה (אופציונלי)",
