    "Stored locally only. Aviary never sends this except as the auth header to your provider.": "נשמר מקומית בלבד. ‏Aviary שולח אותו רק ככותרת אימות אל הספק שלך.",
    "Semantic search": "חיפוש סמנטי",
    "Embed CheckpointStore records via your provider for similarity search.": "מטמיע את רשומות ה‑CheckpointStore דרך הספק שלך לצורך חיפוש דמיון.",
    "Embedding endpoint": "נקודת קצה להטמעה",
    "POST endpoint that returns {data: [{embedding: number[]}]}": "נקודת POST שמחזירה {data: [{embedding: number[]}]}",
    "Embedding model": "מודל הטמעה",
    "e.g. text-embedding-3-small": "לדוגמה: text-embedding-3-small",
    "Embedding API key": "מפתח API להטמעה",
    "Stored locally; used only as the Authorization header.": "נשמר מקומית ומשמש רק ככותרת Authorization.",
    "Auto-embed every export": "הטמעה אוטומטית בכל ייצוא",
    "After each export run, kick the embedding job in the background. Off by default.": "אחרי כל ייצוא, מפעיל את משימת ההטמעה ברקע. כבוי כברירת מחדל.",
    "Rebuild semantic index": "בנייה מחדש של האינדקס הסמנטי",
    "Embed every captured record. Re-running is cheap because cached entries are skipped.": "מטמיע כל רשומה שנאספה. הרצה חוזרת זולה כי רשומות שכבר במטמון מדולגות.",
    "Clear semantic index": "ניקוי האינדקס הסמנטי",
    "Forget every embedded record.": "שוכח את כל הרשומות שהוטמעו.",
    "Integration status": "מצב האינטגרציות",
    "Export settings": "ייצוא הגדרות",
    "Downloads your preferences as JSON. API keys and passwords are replaced with a placeholder, so the file is safe to share; importing it here keeps the credentials already saved on this machine.": "מוריד את ההעדפות שלך כ‑JSON. מפתחות API וסיסמאות מוחלפים במציין מקום, כך שהקובץ בטוח לשיתוף; ייבוא כאן משמר את פרטי הגישה השמורים במחשב זה.",
